WFJ.Data.add("spell", {
  [1219019] = { "周期的な暗黒の効果に一定の確率で、Creeping Darknessを最大$N1回付与します。直接Shadowダメージを与える呪文がこの効果を起爆させ、スタックごとに$N2のダメージを与えます。", nil, 0x78689b68, nil, "um" },
  [1219043] = { "倒れた友か敵の死体を叩き潰し、近くの敵に$N1のダメージを与えます。", nil, 0xea582ef9, nil, "um" },
