  [1219274] = { "他の種族のプリースト呪文を習得すると、このスロットのアビリティが有効になります。", nil, 0x50ae5b37, nil, "um" },
  [1219355] = { "対象を挑発して自分を攻撃させます。ただし、対象がすでに自分を攻撃している場合は効果がありません。", nil, 0x71de38fd, nil, "um" },
  [1219379] = { "対象を挑発して自分を攻撃させます。ただし、対象がすでに自分を攻撃している場合は効果がありません。", nil, 0x71de38fd, nil, "um" },
  [1219475] = { "対象を挑発して自分を攻撃させます。ただし、対象がすでに自分を攻撃している場合は効果がありません。", nil, 0x71de38fd, nil, "um" },
  [1219500] = { "$D1の間、攻撃速度を$N1%上げます。", "攻撃速度が上昇しています。", 0xa077c7f4, 0x778d86da, "uu" },
  [1219501] = { "使用者に向けて次に唱えられる攻撃呪文を跳ね返し、$D1の間、すべての系統の魔法への耐性を$N1上昇させます。", "すべての魔法耐性が$N1上昇しています。", 0x1ca9b76d, 0xa1e52dc2, "uu" },
  [1219503] = { "$D1の間、体の大きさと生み出す脅威を$N1%減少させます。", "体の大きさと脅威の発生量が$N1%減少しています。", 0xf1bbff24, 0xce0fe7d9, "uu" },
  [1219506] = { "マナを$N1回復します。", nil, 0x09fdd6de, nil, "um" },
  [1219507] = { "肩スロットのアイテムに、魔法の呪文と効果による回復量を最大$N1増加させ、マナの回復量を5秒ごとに$N2増加させる効果を永続的に付与します。", nil, 0xddab39b3, nil, "um" },
  [1219510] = { "肩スロットのアイテムに、魔法の呪文と効果による与えるダメージと回復量を最大$N1増加させ、クリティカルヒットの確率を$N2%上昇させる効果を永続的に付与します。", nil, 0x314de3bd, nil, "um" },
  [1219511] = { "肩スロットのアイテムに、スタミナを$N1、Defenseを$N2上昇させる効果を永続的に付与します。", nil, 0x54c249bc, nil, "um" },
  [1219512] = { "肩スロットのアイテムに、Attack Powerを$N1増加させ、クリティカルヒットの確率を$N2%上昇させる効果を永続的に付与します。", nil, 0x811e608c, nil, "um" },
  [1219513] = { "$D1の間、次の$N1回の呪文による回復量を最大$N2増加させます。", "治療呪文の効果が最大$N1増加しています。", 0x9695f8e3, 0xd754af7b, "uu" },
  [1219515] = { "$D1の間、魔法の呪文と効果によるダメージと回復量を最大$N1増加させます。", "呪文ダメージと治療量が最大$N1増加しています。", 0xc0d35181, 0xce30f511, "uu" },
  [1219519] = { "$D1の間、Attack Powerを$N1上昇させます。", "Attack Powerが$N1上昇しています。", 0xb593685a, 0x2905f15b, "uu" },
  [1219520] = { "$D1の間、盾のブロック値を$N1上昇させます。", "ブロック値が$N1上昇しています。", 0xe7882b6e, 0x64e8286f, "uu" },
  [1219539] = { "Naxxramasの中にいる間、あなたの潜在能力を解放します。装備しているSanctifiedアイテム一つにつき、与えるダメージが$N1%、体力が$N2%増加します。（Sanctifiedアイテムを$N3個より多く装備しても、それ以上の効果はありません）", "Naxxramasの中にいる間、あなたの潜在能力を解放します。装備しているSanctifiedアイテム一つにつき、与えるダメージが$N1%、体力が$N2%増加します。", 0x239ff9c8, 0xc451f1c1, "uu" },
  [1219541] = { "対象を挑発して自分を攻撃させます。ただし、対象がすでに自分を攻撃している場合は効果がありません。", nil, 0x71de38fd, nil, "um" },
  [1219548] = { "Naxxramasの中にいる間、あなたの潜在能力を解放します。装備しているSanctifiedアイテム一つにつき、回復量が$N1%、体力が$N2%増加します。（Sanctifiedアイテムを$N3個より多く装備しても、それ以上の効果はありません）", "Naxxramasの中にいる間、あなたの潜在能力を解放します。装備しているSanctifiedアイテム一つにつき、回復量が$N1%、体力が$N2%増加します。", 0xfb50752c, 0x3a3efb98, "uu" },
  [1219552] = { "$N1ヤード以内にいるすべてのパーティーメンバーの、魔法の呪文と効果による与えるダメージと回復量を最大$N2増加させます。この効果は複数の効果源から重ねられません。", "魔法の呪文と効果によるダメージと治療量が最大$N1増加します。この効果は複数の効果源から重複しません。", 0x0c3354b0, 0xc9de4c90, "uu" },
  [1219553] = { "$N3以内にいるすべてのパーティーメンバーの、魔法の呪文と効果による回復量を最大$N1、与えるダメージを最大$N2増加させます。この効果は複数の効果源から重ねられません。", "すべての魔法の呪文と効果による治療量が最大$N1、ダメージが最大$N2増加します。この効果は複数の効果源から重複しません。", 0x828eded3, 0x0de1dc02, "uu" },
  [1219557] = { "$N1ヤード以内にいるすべてのパーティーメンバーの呪文の詠唱速度を$N2%上昇させます。この効果は複数の効果源から重ねられません。", "呪文の詠唱速度が$N1%上昇します。この効果は複数の効果源から重複しません。", 0x251f0459, 0x05f89473, "uu" },
  [1219558] = { "$N1ヤード以内にいるすべてのパーティーメンバーの呪文のクリティカル率を$N2%上昇させます。この効果は複数の効果源から重ねられません。", "$N1ヤード以内のすべてのパーティーメンバーの呪文のクリティカル率が$N2%上昇します。この効果は複数の効果源から重複しません。", 0x0490bbea, 0x0490bbea, "uu" },
  [1219577] = { "Off-Handに永続的なエンチャントを施し、知性を$N1上昇させます。", nil, 0x60a9b17f, nil, "um" },
  [1219578] = { "Off-Handに永続的なエンチャントを施し、精神を$N1上昇させます。", nil, 0xe62ca978, nil, "um" },
  [1219579] = { "Off-Handに永続的なエンチャントを施し、知性を$N1、精神を$N2上昇させます。", nil, 0x0a28ddd8, nil, "um" },
  [1219580] = { "2H Weaponに永続的なエンチャントを施し、Spell Powerを$N1付与します。", nil, 0xe3aaecc8, nil, "um" },
  [1219581] = { "Shieldに永続的なエンチャントを施し、スタミナを$N1上昇させます。", nil, 0x4e82b193, nil, "um" },
  [1219587] = { "Cloakに永続的なエンチャントを施し、敏捷性を$N1上昇させます。", nil, 0x812f211c, nil, "um" },
  [1219740] = { "肩にSoul of the Tacticianを永続的に宿します：\n\n構えを変更した後、次の攻撃アビリティの怒りコストが$N1減少します。", nil, 0xdf824ef3, nil, "um" },
  [1219742] = { "肩にSoul of the War Veteranを永続的に宿します：\n\n構えを解除してから$D1の間、その構えが必要なアビリティを、まだその構えにいるかのように使用できます。", nil, 0x5f737b0f, nil, "um" },
  [1219743] = { "肩にSoul of the Battle Forecasterを永続的に宿します：\n\n構えを発動してから最初の$D1の間、追加の効果を得られます：\n\nBattle Stance/Gladiator Stance：与えるダメージが$N2%増加します。\n\nBerserker Stance：クリティカル率が$N3%上昇します。\n\nDefensive Stance：受けるPhysicalダメージが$N4%減少します。", nil, 0x54969ff6, nil, "um" },
  [1219745] = { "肩にSoul of the Bloodseekerを永続的に宿します：\n\nOverpowerのクリティカルにより、対象のRendの持続時間が最大まで更新されます。", nil, 0xebd4fcb3, nil, "um" },
  [1219747] = { "肩にSoul of the Titanを永続的に宿します：\n\nHeroic Strike、Slam、Overpowerのダメージが$N1%増加します。", nil, 0x4bb8bcc4, nil, "um" },
  [1219748] = { "肩にSoul of the Destroyerを永続的に宿します：\n\nSlamが命中すると、Mortal Strike、Bloodthirst、Shield Slamの残りクールダウンがリセットされます。", nil, 0xb3511461, nil, "um" },
  [1219749] = { "肩にSoul of the Deathboundを永続的に宿します：\n\nDeath Wishのクールダウンを$N1%短縮します。", nil, 0x6d33caab, nil, "um" },
  [1219751] = { "肩にSoul of the Sanguinistを永続的に宿します：\n\n近くの敵が自分のRendとDeep Woundsの両方を受けている間、与えるダメージが$N1%増加します。", nil, 0xec347a3b, nil, "um" },
  [1219752] = { "肩にSoul of the Pristine Blockerを永続的に宿します：\n\n盾のブロック値が$N1増加します。", nil, 0xa3fc2dbf, nil, "um" },
  [1219753] = { "肩にSoul of the Savageを永続的に宿します：\n\nダメージを受けるたび、または自動攻撃でダメージを与えるたびに、怒りを追加で$N1得ます。", nil, 0x812cea45, nil, "um" },
  [1219754] = { "肩にSoul of Enmityを永続的に宿します：\n\nDefensive Stanceで生み出す脅威がすべてさらに$N1%増加し、Gladiator Stanceで与えるダメージがすべて$N2%増加します。", nil, 0x2e92bf79, nil, "um" },
  [1219755] = { "肩にSoul of the Deflectiveを永続的に宿します：\n\nParryするたび、または自分の攻撃がParriedされるたびに、怒りを$N1得ます。", nil, 0x7661e34f, nil, "um" },
  [1219756] = { "肩にSoul of the Revengerを永続的に宿します：\n\nRevengeがFlurryも付与するようになり、次の$N2回のスイングの攻撃速度が$N1%上昇します。", nil, 0xcbcbce57, nil, "um" },
  [1219757] = { "肩にSoul of the Incessantを永続的に宿します：\n\n対象が攻撃をParriesすると、即座にその対象へRetaliateし、武器ダメージの$N1%を与えます。RetaliateはDodged、Blocked、Parriedされることはありませんが、対象ごとに$D1に一度しか発生しません。", nil, 0xf0ea1ade, nil, "um" },
  [1219758] = { "肩にSoul of the Thunderbringerを永続的に宿します：\n\nThunder Clapのクールダウンを$N1%短縮します。", nil, 0xe475b182, nil, "um" },
  [1219760] = { "肩にSoul of the Sentinelを永続的に宿します：\n\nShield Slamの脅威が$N1%増加し、Dodged、Parried、Blockedされるとクールダウンがリセットされます。", nil, 0xa46ccaa4, nil, "um" },
  [1219762] = { "肩にSoul of the Southpawを永続的に宿します：\n\nShield Slamのクールダウンを$D1短縮します。", nil, 0xcb63e17e, nil, "um" },
  [1219763] = { "肩にSoul of the Gladiatorを永続的に宿します：\n\nGladiator Stance中、Bloodrageのクールダウンを$D1短縮します。", nil, 0xcf05ad3a, nil, "um" },
  [1219764] = { "肩にSoul of the Aftershockを永続的に宿します：\n\nShockwaveのクールダウンを$N1%短縮します。", nil, 0xb1f318bc, nil, "um" },
  [1219766] = { "肩にSoul of the Avoidantを永続的に宿します：\n\nFeintがAvoidanceも$D1の間付与するようになり、プレイヤー以外からの範囲攻撃で受けるダメージをすべて$N2%軽減します。", nil, 0xf0f83cd1, nil, "um" },
  [1219767] = { "肩にSoul of the Toxicologistを永続的に宿します：\n\nPoisonsのクリティカルダメージボーナスが$N1%増加します。", nil, 0xc7d102e7, nil, "um" },
  [1219768] = { "肩にSoul of the Executionerを永続的に宿します：\n\nフィニッシュ技は、コンボポイントごとに$N1%の確率で、次のアビリティのエネルギーコストをなくします。", nil, 0x823e6a92, nil, "um" },
  [1219769] = { "肩にSoul of the Opportunistを永続的に宿します：\n\nオープナー技は$N1%の確率で、次のアビリティのエネルギーコストをなくします。", nil, 0x35a70f81, nil, "um" },
  [1219770] = { "肩にSoul of the Butcherを永続的に宿します：\n\nコンボポイントを生み出すアビリティでメインハンド武器が与えるダメージが$N1%増加します。", nil, 0x76d9111b, nil, "um" },
  [1219771] = { "肩にSoul of the Phantomを永続的に宿らせます：\r\n\nVanishのクールダウンを$D1に短縮します。Elusivenessとは併用できません。", nil, 0x1bc330fb, nil, "um" },
  [1219772] = { "肩にSoul of the Scoundrelを永続的に宿らせます：\r\n\nMutilateとSaber Slashのダメージが$N1%増加します。", nil, 0x2dfcb1fc, nil, "um" },
  [1219773] = { "肩にSoul of the Thrill Seekerを永続的に宿らせます：\r\n\nAdrenaline Rushのクールダウンを$D1短縮します。", nil, 0xfe108859, nil, "um" },
  [1219774] = { "肩にSoul of the Shiv Savantを永続的に宿らせます：\r\n\nDaggersでのクリティカルヒット率が$N1%増加します。", nil, 0x0cfc4bb0, nil, "um" },
  [1219775] = { "肩にSoul of the Stalkerを永続的に宿らせます：\r\n\nAmbushアビリティのクリティカルヒット率が$N1%増加します。", nil, 0xf5740008, nil, "um" },
  [1219776] = { "肩にSoul of the Efficientを永続的に宿らせます：\r\n\nフィニッシュムーブのエネルギーコストが$N1%減少します。", nil, 0xd6d7a76d, nil, "um" },
  [1219777] = { "肩にSoul of the Knife Jugglerを永続的に宿らせます：\r\n\nJust a Flesh WoundとBlade Danceが有効な間、Crimson Tempest、Blunderbuss、Fan of Knivesのエネルギーコストが$N1減少し、生成する脅威が$N2%増加します。", nil, 0xc8a196c6, nil, "um" },
  [1219778] = { "肩にSoul of the Shadow Masterを永続的に宿らせます：\r\n\nVanishがその効果時間中、受けるMagicダメージをすべて$N1%軽減するようになりますが、Stealthを付与せず、移動妨害効果も解除しなくなります。", nil, 0x7bbdfaa6, nil, "um" },
  [1219779] = { "肩にSoul of the Equilibristを永続的に宿らせます：\r\n\nフィニッシュムーブは、コンボポイントごとに$N1%の確率で、$D1以内に次に受ける近接攻撃のPhysicalダメージを$N2%軽減します。", nil, 0x27c916bc, nil, "um" },
  [1219780] = { "肩にSoul of the Poised Brawlerを永続的に宿らせます：\r\n\nRolling with the Punchesが、コンボポイントを得るたびにも発動するようになります。", nil, 0xf3489f80, nil, "um" },
  [1219781] = { "肩にSoul of the Black Beltを永続的に宿らせます：\r\n\nRolling with the Punchesにより、スタックごとにアイテムによるアーマーも$N1%増加します（上限$N2%）。", nil, 0xeebbb56a, nil, "um" },
  [1219782] = { "肩にSoul of the Fencerを永続的に宿らせます：\r\n\nターゲットがDodgesまたはParriesするたびに、Main Gaucheのクールダウンがリセットされます。", nil, 0x1f52ac50, nil, "um" },
  [1219783] = { "肩にSoul of the Swashbucklerを永続的に宿らせます：\r\n\nMain Gaucheが近くの追加ターゲット$N1体にも命中するようになり、さらに$D1の間、Sinister Strikeも近くの追加ターゲット$N2体に命中します。これらの追加攻撃はBlade Flurryでは複製されません。", nil, 0xd2a43825, nil, "um" },
  [1219784] = { "肩にSoul of the Bloodthirstyを永続的に宿らせます：\r\n\n有効な間、Main Gaucheにより、Sinister Strikeで与えたダメージすべての$N1%分、体力も回復します。余剰回復はBlood Barrierとなり、最大体力の$N2%までのダメージを吸収します。", nil, 0xa08528c4, nil, "um" },
  [1219785] = { "肩にSoul of the Transfusionistを永続的に宿らせます：\r\n\nLifetapで得られるマナが$N1%増加し、生成する脅威が$N2%減少します。", nil, 0xb75592a0, nil, "um" },
  [1219786] = { "肩にSoul of the Refinedを永続的に宿らせます：\r\n\n呪文と攻撃のクリティカルヒット率が$N1%増加します。", nil, 0xf3d860bd, nil, "um" },
  [1219787] = { "肩にSoul of the Decimatorを永続的に宿らせます：\r\n\nNightfallタレントの発動率が$N1%増加します。Incinerateは、ターゲットの体力に関係なく、$N2%の確率でDecimationを発動させます。", nil, 0xe76090f6, nil, "um" },
  [1219788] = { "肩にSoul of the Rotbringerを永続的に宿らせます：\r\n\n持続性の呪文とFelguardペットのダメージが$N1%増加します。", nil, 0xb6e3a0e3, nil, "um" },
  [1219789] = { "肩にSoul of the Malevolentを永続的に宿らせます：\r\n\nShadowflame、Unstable Affliction、Curse of Agonyの呪文による持続ダメージとFelguardが与えるダメージは、$N1%の確率でShadow Trance効果を付与します。", nil, 0x568af6ea, nil, "um" },
  [1219790] = { "肩にSoul of the Shadowmancerを永続的に宿らせます：\r\n\nShadowboltは、ターゲットにかかっているあなたの効果ごとに与えるダメージが$N1%増加します（最大$N2%）。", nil, 0x038c730d, nil, "um" },
  [1219791] = { "肩にSoul of the Chaos Harbingerを永続的に宿らせます：\r\n\nChaos Boltのクールダウンを$N1%短縮し、Chaos BoltとShadow Boltの与えるダメージを$N2%増加させます。さらに、Chaos BoltでImproved Shadow Boltタレントが発動するようになり、そのチャージが$N3回追加されます（Shadowflameによる追加チャージとは重複しません）。", nil, 0x25cf8583, nil, "um" },
  [1219792] = { "肩にSoul of the Arsonistを永続的に宿らせます：\r\n\nConflagrateでターゲットに命中するたびに、$D1の間Fireダメージが$N1%増加します。最大$N3回までスタックします。", nil, 0x5928b7e4, nil, "um" },
  [1219793] = { "肩にSoul of the Infernal Shepherdを永続的に宿らせます：\r\n\n悪魔ペットが能力値から得るAttack PowerとSpell Damageが$N1%増加します。", nil, 0xfcd8b162, nil, "um" },
  [1219794] = { "肩にSoul of the Demonlordを永続的に宿らせます：\r\n\nMaster Demonologistタレントの効果が$N1%増加します。", nil, 0x6b4b3b96, nil, "um" },
  [1219795] = { "肩にSoul of the Demonic Exorcistを永続的に宿らせます：\r\n\nBanishが即時詠唱になり、あなたが悪魔である間は自分自身にも使用できます。Forbearance中は自分にBanishを使用できず、使用すると$D1の間Forbearanceを受けます。", nil, 0x9a62a4ce, nil, "um" },
  [1219796] = { "肩にSoul of the Painedを永続的に宿らせます：\r\n\nダメージを受けるたびに、あなたとペットは受けたダメージと同じ量のマナを得ます（各回最大$N1 マナ）。発動は数秒に一度だけです。", nil, 0x7ae2ea4c, nil, "um" },
  [1219797] = { "肩にSoul of the Flamewraithを永続的に宿らせます：\r\n\nShadow Cleaveの命中時、$N1%の確率でSoul Shardを得て、Soul Fireのクールダウンがリセットされ、$D1以内の次のSoul Fireが即時詠唱になります。", nil, 0x53c21028, nil, "um" },
  [1219798] = { "肩にSoul of the Fleshfeasterを永続的に宿らせます：\r\n\n$N1ヤード以内の敵をターゲットしている間、Life Tapはターゲットの体力を代償にマナを与えますが、ターゲットへのダメージは$N2%減少します。得られるマナの量は変わりません。", nil, 0xf254472e, nil, "um" },
  [1219799] = { "肩にSoul of the Abyssalを永続的に宿らせます：\r\n\nMetamorphosisが有効な間、攻撃アビリティと悪魔の召喚にSoul Shardsを消費しません。さらに、Shadowburnでターゲットにダメージを与えると、最大体力の$N1%を回復します。", nil, 0xe893887a, nil, "um" },
  [1219800] = { "肩にSoul of the Voidborneを永続的に宿らせます：\r\n\n自分への余剰回復は、ダメージを吸収するシールドに変換されます。このシールドは最大体力の$N1%まで吸収でき、複数の回復で累積します。", nil, 0x7a2839db, nil, "um" },
  [1219801] = { "肩にSoul of the Umbral Bladeを永続的に宿らせます：\r\n\nShadow Cleaveのクールダウンを$D1短縮します。", nil, 0x0d8c8bef, nil, "um" },
  [1219802] = { "肩にSoul of the Ritualistを永続的に宿らせます：\r\n\n悪魔ペットを召喚している間は、生け贄にしたペットを再召喚しない限り、Demonic Sacrificeの効果が持続するようになります。有効にできるDemonic Sacrificeの効果は一度に一つだけです。", nil, 0x342a9f55, nil, "um" },
  [1219803] = { "肩にSoul of the Pain Spreaderを永続的に宿らせます：\r\n\nShadowcleaveの使用後$D1の間、Searing Painが近接範囲内の追加ターゲット$N2体にも命中します。", nil, 0x8c03a8b1, nil, "um" },
  [1219804] = { "肩にSoul of the Misleaderを永続的に宿らせます：\r\n\nDistracting Shotの使用後$D1の間、生成する脅威が$N1%増加します。", nil, 0x90d1ee81, nil, "um" },
  [1219805] = { "肩にSoul of the Preyseekerを永続的に宿らせます：\r\n\nクリーチャータイプを追跡している間、そのクリーチャータイプに与えるダメージが$N1%増加します。", nil, 0x3a0917db, nil, "um" },
  [1219806] = { "肩にSoul of the Sharpshooterを永続的に宿らせます：\r\n\nAimed Shotの後$D1以内に使用する次のShotアビリティのダメージが$N2%増加します。", nil, 0xe4f43428, nil, "um" },
  [1219807] = { "肩にSoul of the Hazard Harrierを永続的に宿らせます：\r\n\nAimed Shotは、あなたの罠の効果を受けているターゲットに与えるダメージが$N1%増加します。", nil, 0x773fa0d0, nil, "um" },
  [1219808] = { "肩にSoul of the Alternatorを永続的に宿らせます：\r\n\n直前に使用したダメージを与えるShotが今回と異なる場合、ダメージを与えるShotアビリティのダメージが$N1%増加します。", nil, 0x4b7438ab, nil, "um" },
  [1219809] = { "肩にSoul of the Toxinologistを永続的に宿らせます：\r\n\nSerpent Stingのダメージが、通常の効果時間にわたってAttack Powerの$N1%分増加します。", nil, 0xa58e22df, nil, "um" },
  [1219810] = { "肩にSoul of the Bounty Hunterを永続的に宿らせます：\r\n\nプレイヤーが操作していないターゲットに対するKill Shotのダメージが$N1%増加します。", nil, 0xda55dbbd, nil, "um" },
  [1219811] = { "肩にSoul of the Trick Shooterを永続的に宿らせます：\r\n\nKill Shotのクールダウンが$N1%短縮されます。Rapid Killingをエングレーブした状態でRapid Fireが有効な間、Kill Shotのクールダウンがなくなり、プレイヤーが操作していないターゲットに使用すると、$N3%のダメージの追加Kill Shotを$N2発放ちます（最小射程あり）。", nil, 0x3d746cf2, nil, "um" },
  [1219812] = { "肩にSoul of the Beast Tenderを永続的に宿らせます：\r\n\nBeastペットが能力値から得るAttack Powerが$N1%増加します。", nil, 0xa266e059, nil, "um" },
  [1219813] = { "肩にSoul of the Hound Masterを永続的に宿らせます：\r\n\nBeastペットのFocus回復速度が$N1%増加します。", nil, 0xbbc6f103, nil, "um" },
  [1219815] = { "肩にSoul of the Alpha Tamerを永続的に宿らせます：\r\n\nペットのFocus回復速度が$N1%増加します。", nil, 0xe02c301c, nil, "um" },
  [1219816] = { "肩にSoul of the Huntsmanを永続的に宿らせます：\r\n\nMongoose Biteは、$D1の間、ターゲットのDodge率を$N1%低下させ、あなたの命中率を$N2%増加させます。", nil, 0xb06629f3, nil, "um" },
  [1219818] = { "肩にSoul of the Retaliatorを永続的に宿らせます：\r\n\nターゲットがParriesまたはBlocksした時、またはあなたの近接攻撃がミスした時にも、Mongoose Biteが$D1の間使用可能になります。", nil, 0x4c1c911d, nil, "um" },
  [1219819] = { "肩にSoul of Echoesを永続的に宿らせます：\r\n\nRaptor Strikeは、$D1以内に使用する次の他の近接アビリティ（Wing Clipを除く）の与えるダメージを$N2%増加させます。", nil, 0xb36bf6ba, nil, "um" },
  [1219820] = { "肩にSoul of the Lethal Lasherを永続的に宿らせます：\r\n\nRaptor StrikeとWyvern Strikeによるメインハンド武器のダメージが$N1%増加します。", nil, 0x32c0d640, nil, "um" },
  [1219821] = { "肩にSoul of the Kineticistを永続的に宿らせます：\r\n\n持続ダメージは$N1%の確率で、Strikeアビリティの一つのクールダウンをリセットします。常に残りクールダウンが最も長いStrikeが選ばれます。", nil, 0x7f1ab835, nil, "um" },
  [1219822] = { "肩にSoul of the Strategistを永続的に宿らせます：\r\n\nWyvern Strikeの持続ダメージが$N1%増加し、ペットの最大フォーカスが$N2増加します。", nil, 0x168d3e9c, nil, "um" },
  [1219823] = { "肩にSoul of the Deadly Strikerを永続的に宿らせます：\r\n\nMongoose BiteとすべてのStrikeの直撃ダメージが$N1%増加します。", nil, 0xd5fad7da, nil, "um" },
  [1219824] = { "肩にSoul of the Hastened Healerを永続的に宿らせます：\r\n\nFlash Healの詠唱時間が$D1、Greater Healの詠唱時間が$D2短縮されます。", nil, 0x9ab400ed, nil, "um" },
  [1219825] = { "肩にSoul of the Refinedを永続的に宿らせます：\r\n\n呪文と攻撃のクリティカルヒット率が$N1%増加します。", nil, 0xf3b6131f, nil, "um" },
  [1219826] = { "肩にSoul of the Celebrantを永続的に宿らせます：\r\n\nPrayer of HealingとCircle of Healingのクリティカルヒット率が$N1%増加します。", nil, 0x710f3501, nil, "um" },
  [1219827] = { "肩にSoul of the Faithfulを永続的に宿らせます：\r\n\n詠唱中も、マナ回復の$N1%が継続します。", nil, 0x0830d48d, nil, "um" },
  [1219828] = { "肩にSoul of the Serendipitousを永続的に宿らせます：\r\n\n持続回復は$N1%の確率で、詠唱時間が10秒未満の次の呪文を即時詠唱にします。", nil, 0x24bd33e1, nil, "um" },
  [1219829] = { "肩にSoul of the Resonantを永続的に宿らせます：\r\n\nCircle of HealingとPenanceは、ターゲットに$D1かけてその回復量の$N1%を回復する持続回復効果も付与します。", nil, 0xb78e45a1, nil, "um" },
  [1219830] = { "肩にSoul of the Devoteeを永続的に宿らせます：\r\n\nPrayer of Mendingのチャージが$N1回追加されます。", nil, 0xe02e70d2, nil, "um" },
  [1219831] = { "肩にSoul of the Archbishopを永続的に宿らせます：\r\n\nCircle of Healingは、対象パーティで最も傷ついたメンバーへの回復量が$N1%増加します。", nil, 0x6a8a1a27, nil, "um" },
  [1219832] = { "肩にSoul of the Penitentを永続的に宿らせます：\r\n\nPenanceのクールダウンを$D1短縮します。", nil, 0x9d26bb1c, nil, "um" },
  [1219833] = { "肩にSoul of the Soul Warderを永続的に宿らせます：\r\n\nPower Word: Shieldが吸収するダメージが$N1%増加します。", nil, 0xcd0b1c0f, nil, "um" },
  [1219834] = { "肩にSoul of the Twilight Walkerを永続的に宿らせます：\r\n\nShadowform中でもFlash Healを詠唱できます。", nil, 0xddccd53e, nil, "um" },
  [1219835] = { "肩にSoul of the Mind Breakerを永続的に宿らせます：\r\n\nMind Blastのクリティカルヒットは、次のMind Flayの効果時間を$N1%短縮し、その総ダメージを$N2%増加させます。", nil, 0xd3ce0447, nil, "um" },
  [1219836] = { "肩にSoul of the Deathdealerを永続的に宿らせます：\r\n\nShadow Word: Deathのクールダウンを$D1短縮します。", nil, 0x85a70d75, nil, "um" },
  [1219837] = { "肩にSoul of the Spirit Fontを永続的に宿らせます：\r\n\nShadow Word: Painはダメージを与えた時、Spirit Tapのタレントポイントごとに$N1%の確率でSpirit Tapタレントを発動させます。Shadow Word: Painが有効なターゲットが死亡した時は、タレントポイントごとに$N2%の確率で発動させます。Inner Focusにも、タレントポイントごとに$N3%の確率でSpirit Tapを発動させる効果があります。", nil, 0xc60a4683, nil, "um" },
  [1219838] = { "肩にSoul of the Zealotを永続的に宿らせます：\r\n\nSpirit Tapが有効な間、与えるShadowダメージが$N1%増加します。", nil, 0x67a3a9a3, nil, "um" },
  [1219839] = { "肩にSoul of the Unwavering Defilerを永続的に宿らせます：\r\n\nMind Flayはダメージを受けても効果時間が減らなくなり、詠唱時にターゲットへ無償のMind Spikeを放ちます。", nil, 0xd3d17c8f, nil, "um" },
  [1219840] = { "肩にSoul of the Contemnorを永続的に宿らせます：\r\n\nMind Spikeが即時詠唱になり、与えるダメージが$N1%増加し、他の呪文をチャネリング中でも詠唱できるようになります。", nil, 0xf37bd08a, nil, "um" },
  [1219841] = { "肩にSoul of the Plaguebringerを永続的に宿らせます：\r\n\nPain and SufferingのルーンでDevouring Plagueの効果時間を更新できるようになります。", nil, 0x05886fbb, nil, "um" },
  [1219842] = { "肩にSoul of the Reverberantを永続的に宿らせます：\r\n\nTemporal Beaconsの持続時間が$N1%延長されます。", nil, 0x309939fb, nil, "um" },
  [1219843] = { "肩にSoul of the Chronohealerを永続的に宿らせます：\r\n\n時間魔法による回復量がすべて$N1%増加します。", nil, 0x38053f49, nil, "um" },
  [1219844] = { "肩にSoul of Temporal Longingを永続的に宿らせます：\r\n\nRegenerationでターゲットを回復するたびに、Rewind Timeの残りクールダウンが$D1短縮されます。", nil, 0xb93c079f, nil, "um" },
  [1219845] = { "肩にSoul of the Precognitiveを永続的に宿らせます：\r\n\nArcane Missilesはダメージを与えるたびに、基本マナコストの$N1%を返還します。", nil, 0xed6e9d75, nil, "um" },
  [1219846] = { "肩にSoul of the Arcanistを永続的に宿らせます：\r\n\nArcane BlastでMissile Barrageが発動する確率がさらに$N1%増加し、Missile BarrageはArcane Missilesと同様にRegenerationにも効果を及ぼすようになります。", nil, 0xed8c7d34, nil, "um" },
  [1219847] = { "肩にSoul of the Eternal Caretakerを永続的に宿らせます：\r\n\nMass RegenerationによるTemporal Beaconsの持続時間が$D1になります。", nil, 0x93607967, nil, "um" },
  [1219848] = { "肩にSoul of the Spellbiderを永続的に宿らせます：\r\n\nArcane Blastのスタックごとのダメージ増加量がさらに$N1%増えます。", nil, 0x84091821, nil, "um" },
  [1219849] = { "肩にSoul of the Wardshaperを永続的に宿らせます：\r\n\nMana Shield、Fire Ward、Frost Wardの吸収するダメージが$N1%増加し、さらに$D1の間、ターゲットにTemporal Beaconを付与します。", nil, 0xf08d0200, nil, "um" },
  [1219850] = { "肩にSoul of Winter's Graspを永続的に宿らせます：\r\n\nFingers of Frostルーンの発動率がさらに$N1%増加します。", nil, 0x4ea4cb97, nil, "um" },
  [1219851] = { "肩にSoul of the Cryomancerを永続的に宿らせます：\r\n\nFrostboltとSpellfrost Boltの与えるダメージが$N1%増加します。", nil, 0xa97bced4, nil, "um" },
  [1219852] = { "肩にSoul of the Evokerを永続的に宿らせます：\r\n\nEvocationをチャネリング中、すべてのダメージを無効化します。", nil, 0xb8a6b955, nil, "um" },
  [1219853] = { "肩にSoul of the Elementalistを永続的に宿らせます：\r\n\n前回と異なる系統の呪文を詠唱するたびに、$D1の間、与えるダメージが$N1%増加します。", nil, 0x5ab56f0c, nil, "um" },
  [1219854] = { "肩にSoul of the Magical Armorerを永続的に宿らせます：\r\n\nMage Armorは詠唱中のマナ回復をさらに$N1%増加させます。Molten Armorは呪文のダメージと回復量を$N2増加させます。Ice ArmorはFingers of Frostの発動率を$N3%増加させます。", nil, 0xd484e42d, nil, "um" },
  [1219855] = { "肩にSoul of the Kindlerを永続的に宿らせます：\r\n\nFire呪文が生成する脅威が$N1%減少します。", nil, 0xc429d5b8, nil, "um" },
  [1219856] = { "肩にSoul of Fiery Convergenceを永続的に宿らせます：\r\n\nPyroblastは、Fireballの持続効果を受けているターゲットに与えるダメージが$N1%増加します。", nil, 0x42ed8f92, nil, "um" },
  [1219857] = { "肩にSoul of the Perpetual Blazeを永続的に宿らせます：\r\n\nFireballの持続効果は、その効果時間にわたって、直撃ダメージの$N1%に等しいダメージ増加を得ます。", nil, 0xbb4a5dbb, nil, "um" },
  [1219858] = { "肩にSoul of the Pyromaniacを永続的に宿らせます：\r\n\nFire Blastにより、次のFire呪文のクリティカルヒット率も$D1の間$N1%増加します。", nil, 0x7087ef35, nil, "um" },
  [1219859] = { "肩にSoul of the Igniterを永続的に宿らせます：\r\n\nIgniteタレントの与えるダメージが$N1%増加します。", nil, 0x00814fae, nil, "um" },
  [1219860] = { "肩にSoul of the Torcherを永続的に宿らせます：\r\n\nFireball、Frostfire Bolt、Balefire Boltは、ターゲットにかかっているあなたのFire効果ごとにダメージが$N1%増加します（最大$N2%）。", nil, 0x8eec4150, nil, "um" },
  [1219861] = { "肩にSoul of the Pristine Blockerを永続的に宿します：\n\n盾のブロック値が$N1増加します。", nil, 0xa3d99c99, nil, "um" },
  [1219862] = { "肩にSoul of the Lightwardenを永続的に宿らせます：\r\n\nBlockした時に体力を$N1回復します。回復は数秒に一度だけです。", nil, 0x76f4d5d7, nil, "um" },
  [1219863] = { "肩にSoul of the Radiant Defenderを永続的に宿らせます：\r\n\nHoly Shieldのチャージがなくなり、常に効果時間いっぱい持続するようになります。さらに、そのダメージが盾のブロック値の$N1%分増加します。", nil, 0x7eefa41c, nil, "um" },
  [1219864] = { "肩にSoul of the Shieldbearerを永続的に宿らせます：\r\n\nHoly ShieldによるBlock率の上昇量が$N1%増加します。", nil, 0x9d8d9669, nil, "um" },
  [1219865] = { "肩にSoul of the Bastionを永続的に宿らせます：\r\n\nHoly Shieldが有効な間、受けるダメージが$N1%減少します。", nil, 0xe371efdf, nil, "um" },
  [1219866] = { "肩にSoul of the Reckonerを永続的に宿らせます：\r\n\nReckoningタレントが、Blockした時にタレントポイントごとに$N1%の確率で発動するようになります。", nil, 0xf7d85cb2, nil, "um" },
  [1219867] = { "肩にSoul of the Ironcladを永続的に宿らせます：\r\n\nBlessing of Sanctuaryを自分に使用すると、全能力値も$N1%増加します。", nil, 0xb089c840, nil, "um" },
  [1219868] = { "肩にSoul of the Guardianを永続的に宿らせます：\r\n\nShield of the Righteousにより、次のHoly Lightが即時詠唱になります。自分に使用した場合、マナコストの$N1%が返還され、Guarded by the Lightの影響を受けません。", nil, 0x29738ef7, nil, "um" },
  [1219869] = { "肩にSoul of the Peacekeeperを永続的に宿らせます：\r\n\n味方がJudgement of LightまたはJudgement of Wisdomを発動させる確率が$N1%になります。", nil, 0x2d7175c3, nil, "um" },
  [1219870] = { "肩にSoul of the Refinedを永続的に宿らせます：\r\n\n呪文と攻撃のクリティカルヒット率が$N1%増加します。", nil, 0xf3d7d99f, nil, "um" },
  [1219871] = { "肩にSoul of the Exemplarを永続的に宿らせます：\r\n\nFlash of Light、Holy Light、Beacon of Lightがターゲットの体力を全回復させると、そのパーティ全員の体力も$N1回復します。", nil, 0x31595f8b, nil, "um" },
  [1219872] = { "肩にSoul of the Inquisitorを永続的に宿らせます：\r\n\nHoly Shockのクリティカルヒット率が$N1%増加します。", nil, 0xf8fc7d11, nil, "um" },
  [1219873] = { "肩にSoul of the Sovereignを永続的に宿らせます：\r\n\nConsecrationの与えるダメージが$N1%増加します。", nil, 0xe578c6c3, nil, "um" },
  [1219874] = { "肩にSoul of the Dominusを永続的に宿らせます：\r\n\nあなた自身がBeacon of Lightの対象でない間、Consecration、Exorcism、Holy Shock、Holy Wrath、Hammer of Wrathで与えたダメージの$N1%分、Beacon of Lightの対象も回復します。", nil, 0x4253c983, nil, "um" },
  [1219875] = { "肩にSoul of the Vindicatorを永続的に宿らせます：\r\n\nDivine Lightのクールダウンを$N1%短縮します。", nil, 0x0a2aa45f, nil, "um" },
  [1219876] = { "肩にSoul of the Altruistを永続的に宿らせます：\r\n\nBeacon of Lightの対象への回復は、最も近い負傷した味方ターゲットもその$N1%分回復します。", nil, 0x68861e5c, nil, "um" },
  [1219877] = { "肩にSoul of the Arbiterを永続的に宿らせます：\r\n\nJudgement of LightとJudgement of Wisdomが、Judgement of the Crusaderの効果も付与します。", nil, 0x9db1e989, nil, "um" },
  [1219878] = { "肩にSoul of the Sealbearerを永続的に宿らせます：\r\n\nSeal of Command、Seal of Righteousness、Seal of Martyrdom、Sunlightの与えるダメージが$N1%減少しますが、別のSealを使用した後も$N2秒間、または三つ目のSealを使用するまで持続するようになります。Judgementsは、有効な複数のSealsを発動できるようになります。", nil, 0x66204e45, nil, "um" },
  [1219879] = { "肩にSoul of the Justicarを永続的に宿らせます：\r\n\nダメージを与えるJudgementsの与えるダメージが$N1%増加し、Judgementsがターゲット上のSealsを消費しなくなります。Judgementsは、有効な複数のSealsを発動できるようになります。", nil, 0xfab12449, nil, "um" },
  [1219880] = { "肩にSoul of the Judicatorを永続的に宿らせます：\r\n\nJudgementアビリティのクールダウンを$D1短縮しますが、Judgementsの与えるダメージが$N2%減少します。", nil, 0x4e512e5b, nil, "um" },
  [1219881] = { "肩にSoul of the Ascendantを永続的に宿らせます：\r\n\nJudgementにより、$D1の間Holyダメージが$N1%増加します。最大$N3回までスタックします。", nil, 0xf0c82a56, nil, "um" },
  [1219882] = { "肩にSoul of the Retributorを永続的に宿らせます：\r\n\nCrusader Strikeのダメージが$N1%増加します。", nil, 0x1b794919, nil, "um" },
  [1219883] = { "肩にSoul of the Excommunicatorを永続的に宿らせます：\r\n\n両手近接武器による通常攻撃は、$D1以内に使用する次のExorcismのダメージを$N2%増加させます。最大$N3回までスタックします。", nil, 0x3feea6a8, nil, "um" },
  [1219884] = { "肩にSoul of the Lightbringerを永続的に宿らせます：\r\n\nHoly Shockの与えるダメージが$N1%増加します。", nil, 0x9dac3aaf, nil, "um" },
  [1219885] = { "肩にSoul of the Exileを永続的に宿らせます：\r\n\nExorcismのクールダウンを$D1短縮し、与えるダメージを$N2%増加させます。", nil, 0x49e77c8f, nil, "um" },
  [1219886] = { "肩にSoul of the Templarを永続的に宿らせます：\r\n\n片手武器を装備している間、Crusader StrikeがSealsのJudgement効果を発動させますが、Sealは消費しません。", nil, 0xbf03dfa5, nil, "um" },
  [1219887] = { "肩にSoul of the Windwalkerを永続的に宿らせます：\r\n\n受け流し、回避、ブロックした後の次の3回のスイングで、攻撃速度が$N1%増加します。", nil, 0xae1e61ed, nil, "um" },
  [1219888] = { "肩にSoul of the Shield Masterを永続的に宿らせます：\r\n\n受け流しと回避でも、Shield Masteryのルーンアビリティが発動します。", nil, 0x0504a004, nil, "um" },
  [1219889] = { "肩にSoul of the Totemic Protectorを永続的に宿らせます：\r\n\nStoneskin Totemは受けるPhysicalダメージも$N1%軽減し、Windwall Totemは受けるMagicalダメージも$N2%軽減します。", nil, 0x0b18bf10, nil, "um" },
  [1219890] = { "肩にSoul of the Shock-Absorberを永続的に宿らせます：\r\n\nFlame Shockにより、$D1の間、または攻撃をBlockするまで、Block率も$N1%増加します。", nil, 0xac5cd6ca, nil, "um" },
  [1219891] = { "肩にSoul of the Spiritual Bulwarkを永続的に宿らせます：\r\n\nBlockするたびに、$D1の間Block量がSpell Damageの$N1%分増加します。最大$N3回までスタックします。", nil, 0xc2b0eddc, nil, "um" },
  [1219892] = { "肩にSoul of the Maelstrombringerを永続的に宿らせます：\r\n\n攻撃をBlockするたびに、$N1%の確率でMaelstrom Weaponルーンが発動します。", nil, 0x98ad705b, nil, "um" },
  [1219893] = { "肩にSoul of the Lavawalkerを永続的に宿らせます：\r\n\nStormstrike、Lava Burst、Molten Blastでターゲットにダメージを与えると、$D1の間、受けるダメージもすべて$N1%軽減されます。", nil, 0xfa020d01, nil, "um" },
  [1219894] = { "肩にSoul of the True Alphaを永続的に宿らせます：\r\n\nSpirit of the Alphaを自分に使用すると、体力が$N1%、生成する脅威が$N2%、与えるダメージがすべて$N3%増加します。", nil, 0x598d83ec, nil, "um" },
  [1219895] = { "肩にSoul of the Totemkeeperを永続的に宿らせます：\r\n\n味方に効果を及ぼすトーテムの効果範囲が$N1ヤードに拡大します。", nil, 0x26b268a9, nil, "um" },
  [1219896] = { "肩にSoul of the Ancestorsを永続的に宿らせます：\r\n\nHealing Wave、Lesser Healing Wave、Riptideを詠唱した後、$N1%の確率で、その呪文の基本コストの$N2%に等しいマナを得ます。", nil, 0x18780f59, nil, "um" },
  [1219897] = { "肩にSoul of the Spiritweaverを永続的に宿らせます：\r\n\nHealing Waveが近くの追加ターゲットに跳ぶようになります。跳ぶたびに回復効果が$N1%減少し、最大$N2体の追加ターゲットに跳びます。", nil, 0xcc0088f5, nil, "um" },
  [1219898] = { "肩にSoul of the Waterwalkerを永続的に宿らせます：\r\n\n持続性でないダメージと回復のクリティカルヒットは、$N1%の確率でWater Shieldを発動させるようになります。ただし、チャージは消費せず、クールダウンも発生しません。", nil, 0x8ff1a2e1, nil, "um" },
  [1219899] = { "肩にSoul of the Stormtenderを永続的に宿らせます：\r\n\nChain Lightningは、直近のEarth Shieldの対象も、与えたダメージの$N1%分回復するようになります。", nil, 0xaf285f89, nil, "um" },
  [1219900] = { "肩にSoul of the Elemental Seerを永続的に宿らせます：\r\n\nChain Healの回復量とChain Lightningのダメージが$N1%増加します。", nil, 0x9ad749dc, nil, "um" },
  [1219901] = { "肩にSoul of the Vitalistを永続的に宿らせます：\r\n\nRiptideがChain Healの回復量をさらに$N1%増加させます。", nil, 0xac47edcc, nil, "um" },
  [1219902] = { "肩にSoul of the Spirithealerを永続的に宿らせます：\r\n\nChain Healの詠唱時間を$D1短縮します。", nil, 0x62a088c4, nil, "um" },
  [1219903] = { "肩にSoul of the Refinedを永続的に宿らせます：\r\n\n呪文と攻撃のクリティカルヒット率が$N1%増加します。", nil, 0xf3d86031, nil, "um" },
  [1219904] = { "肩にSoul of the Chieftainを永続的に宿らせます：\r\n\nFlurryタレントによる攻撃速度の上昇がさらに$N1%増加します。", nil, 0x15deb29a, nil, "um" },
  [1219905] = { "肩にSoul of the Furychargedを永続的に宿らせます：\r\n\nStatic Shockの発動率が$N1%増加します（二刀流中は$N2%）。", nil, 0xde6f8cb0, nil, "um" },
  [1219906] = { "肩にSoul of the Stormbreakerを永続的に宿らせます：\r\n\nStormstrikeのメインハンドダメージが$N1%増加します。", nil, 0x5d83820c, nil, "um" },
  [1219907] = { "肩にSoul of the Tempestを永続的に宿らせます：\r\n\nStatic Shockをエングレーブしている間、Lightning BoltまたはChain Lightningでターゲットに命中するたびに、Lightning Shieldのチャージが増えます（最大$N1チャージ）。さらに、Static Shockをエングレーブしている間、Lightning Shieldがクリティカルダメージを与えられるようになります。", nil, 0xfd19cb21, nil, "um" },
  [1219908] = { "肩にSoul of the Seismic Smasherを永続的に宿らせます：\r\n\nStormstrikeとLava Lashのダメージが$N1%増加します。両手武器を使用している場合、この効果は$N2%に増加します。", nil, 0x9f9f5f7a, nil, "um" },
  [1219909] = { "肩にSoul of the Flamebringerを永続的に宿らせます：\r\n\nStormstrike、Lava Lash、Lava Burstのクリティカルヒットは、与えたダメージの$N1%を$D1かけてターゲットに炎上ダメージとして与えます。", nil, 0x796df1fb, nil, "um" },
