  [1219911] = { "肩にSoul of the Raging Flameを永続的に宿らせます：\r\n\nLava Burstは、ターゲットのFlame Shockの効果時間も$D1に戻します。", nil, 0x9c74d4f5, nil, "um" },
  [1219912] = { "肩にSoul of the Elemental Masterを永続的に宿らせます：\r\n\n呪文のクリティカルヒットは、$N1%の確率でElemental Focusタレントを発動させるようになります。", nil, 0xcd180551, nil, "um" },
  [1219913] = { "肩にSoul of the Tribesmanを永続的に宿らせます：\r\n\nSpirit of the AlphaアビリティによるLoyal Betaが、Fire、Frost、Natureダメージも$N1%増加させるようになります。", nil, 0x93bc1d68, nil, "um" },
  [1219914] = { "肩にSoul of the Spirit Guideを永続的に宿らせます：\r\n\nClearcastingが有効な間、Physical以外のダメージが$N1%増加します。", nil, 0xe4e9a6bd, nil, "um" },
