  [1219921] = { "肩にSoul of the Ferociousを永続的に宿らせます：\r\n\nEnrageのクールダウンを$D1短縮し、Enrageでアーマーが低下しなくなります。", nil, 0x0db0af0a, nil, "um" },
  [1219922] = { "肩にSoul of the Shifterを永続的に宿らせます：\r\n\nBear FormとDire Bear Formで生成するすべての脅威がさらに$N1%増加し、Cowerがターゲットに対する脅威をすべて除去するようになりますが、クールダウンが$D1長くなります。", nil, 0xb13873a4, nil, "um" },
